#ifndef MI_DECOMP_DISPATCH_HPP
#define MI_DECOMP_DISPATCH_HPP

// Developer builds only (-DMI_DECOMP=ON): picks the decompiled or the recompiled original version of each function in
// decomp/functions.txt. The dispatchers themselves are generated by scripts/decomp_dispatch.py (build/decomp/gen).

#include "recomp.h"

namespace mi::decomp {
    // check: run side by side with the original in check mode. read: never run twice; checked by reading.
    enum class Method { Check, Read };

    struct Entry {
        const char* name;
        recomp_func_t* orig;
        recomp_func_t* decomp;
        Method method;
        bool ret64; // returns a 64-bit value: the check also compares r3 and the odd float return registers
    };

    // Read the on/off list (MI_DECOMP_LIST or decomp/functions.txt) and MI_DECOMP_OFF. Call once at startup.
    void init();
    void call(int id, uint8_t* rdram, recomp_context* ctx);
}

extern "C" const mi::decomp::Entry mi_decomp_entries[];
extern "C" const int mi_decomp_entry_count;

#endif
